      pt: "Uma floresta antiga que é Património Mundial da UNESCO. Imagina que és um explorador a viajar por uma selva onde elefantes selvagens vagueiam e os gibões chamam através das copas das árvores.",
      fr: "Une forêt ancienne classée au patrimoine mondial de l'UNESCO. Imaginez que vous êtes un explorateur voyageant dans une jungle où des éléphants sauvages errent et où les gibbons appellent à travers la canopée.",
